import{z as s,x as A,o as e,c as l,q as n,j as r,D as E,d as t,s as i,S as B}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"货币层次与支付","description":"","frontmatter":{"title":"货币层次与支付","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/money-as-medium.md","filePath":"econ/money-as-medium.md","lastUpdated":1791063341000}'),p={name:"econ/money-as-medium.md"};function d(m,a,c,h,_,D){const o=A("Mermaid");return e(),l("div",null,[a[2]||(a[2]=n('<h1 id="货币层次与支付" tabindex="-1">货币层次与支付 <a class="header-anchor" href="#货币层次与支付" aria-label="Permalink to &quot;货币层次与支付&quot;">​</a></h1><div class="epigraph"><p>货币首先是被广泛接受的支付手段；把凡能保值的东西都叫货币，层次就无法接到数量方程。</p><footer>—— Hicks, A Suggestion for Simplifying the Theory of Money, Economica 1935；对照 Friedman 对货币作为暂时购买力栖所的整理</footer></div><p><a href="/econ/adjustment-cost-invest">上一课</a>（投资调整成本）。在此之上，长期人均产出拆成 \\(K\\)、\\(h\\) 与剩余 \\(A\\)。那些是实物账户。本课换对象：交易如何清算。增长核算不告诉我们哪一种债权算「钱」。后课的 \\(MV=Py\\)、铸币税和银行负债，都默认本课已经把<strong>支付手段</strong>与邻近资产分开，不再从物物交换的寓言重讲。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>核算里的 \\(Y\\) 用某种记账单位计价，但记账单位不必等于流通中的支付工具。若把货币定义成一切财富，数量方程没有独立的 \\(M\\)。若只认铸币与纸币，又会漏掉可开支票的存款——而存款正是后课中介的负债。缺口是：按<strong>流动性与支付功能</strong>分层，而不是先写央行反应函数。</p><p>Hicks（1935）把货币需求从边际效用的货物清单里提出来，改成对流动性的需求：持有货币是为了在买卖不同步时不必卖掉其他资产。Friedman 后来把货币写成暂时的购买力栖所。本课钉功能与口径；流通速度与中性是下一课。</p><p><span class="marginnote">「需求双重巧合」用例子读：你会弹吉他、想要面包；面包师想找人修水管、不想要吉他——物物交换要求「我有的正好是你想要的、你有的正好是我想要的」同时成立，三人凑齐都难。货币把凑配问题变成两步：先把手里的东西换成钱，再用钱买任何东西。</span></p><p><span class="marginnote">三项功能常并列：交换媒介、计价单位、价值储藏。后两项许多资产也能做。使 \\(M\\) 可测的，是它在交易中被<strong>按面值接受</strong>，而不必先找到配对的需求双重巧合。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>记 \\(M0\\)（或基础货币）为通货加准备金；\\(M1\\) 再加活期与可转让存款；\\(M2\\) 再加储蓄与若干定期。层次是统计约定，边界随监管与支付技术移动。本课要的不是某一年的精确表，而是：进入 \\(M\\) 的东西，必须能直接结清对货物与要素的支付，或可几乎无成本地转成这种手段。</p><p><span class="marginnote">三层的门槛记成一句话：能不能<strong>当场</strong>付款。\\(M0\\) 是央行发的钱（纸币 + 银行存在央行的准备金）；\\(M1\\) 加上你刷卡、扫码就能花的活期存款；\\(M2\\) 再加要先解约、牺牲一点利息才能花的定期。越往下流动性越差——门槛不是「值多少钱」，是「能不能直接结清交易」。</span></p>',11)),(e(),r(B,null,{default:E(()=>[i(o,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20UA%5B%22%E8%AE%A1%E4%BB%B7%E5%8D%95%E4%BD%8D%22%5D%20--%3E%20P%5B%22%E4%BB%B7%E6%A0%BC%E6%8C%87%E6%95%B0%20P%22%5D%0A%20%20MOE%5B%22%E6%94%AF%E4%BB%98%E6%89%8B%E6%AE%B5%20M%22%5D%20--%3E%20PAY%5B%22%E7%BB%93%E6%B8%85%E4%BA%A4%E6%98%93%22%5D%0A%20%20SOV%5B%22%E4%BB%B7%E5%80%BC%E5%82%A8%E8%97%8F%22%5D%20--%3E%20ASSET%5B%22%E6%9B%B4%E5%B9%BF%E7%9A%84%E8%B5%84%E4%BA%A7%22%5D%0A%20%20PAY%20--%3E%20QTM%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%95%B0%E9%87%8F%E6%96%B9%E7%A8%8B%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=n('<p>支付与中介尚未分开：公众持有的存款已经是银行负债，<a href="/econ/why-intermediaries">中介功能</a>会回来写转换；本课只认它此刻是 \\(M\\) 的一部分。准备金与内生存款乘数是后课银行课序，这里不提前做货币乘数故事。</p><h3 id="内部货币与外部货币" tabindex="-1">内部货币与外部货币 <a class="header-anchor" href="#内部货币与外部货币" aria-label="Permalink to &quot;内部货币与外部货币&quot;">​</a></h3><p>外部货币是私人部门对政府（含央行）的净债权：通货与准备金。内部货币是私人之间的存款：对一家银行是负债、对持有人是资产，加总时对冲。数量方程里用哪一个 \\(M\\)，会改变「谁在征收通胀税」。下一课先用一个加总 \\(M\\)；铸币税再拆开基础货币。</p><p>支付系统分两层：央行货币结算银行间净额，存款货币结算公众。本课不写 RTGS 工程。层次边界随货币市场基金与支付账户漂移；定义必须随制度改，否则速度表现为假突变。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>没有被广泛接受的支付手段，交易必须配对或每次重新议价用哪种商品清算。货币降低的是这笔匹配成本，不是把 \\(A\\) 提高一截的同一机制——增长课的 \\(A\\) 是生产效率，本课的 \\(M\\) 是交易技术。一旦某种负债被当成货币，对它的超额供给会先表现在名义支出上，这是后课数量方程的入口。</p><p>可转让存款能进 \\(M1\\)，是因为结算系统让它与通货几乎一对一兑换。若挤兑使兑换中断，同一负债就不再按面值充当支付手段——那是银行课，不是本课把 \\(M\\) 写成恒定乘数。</p>',7)),(e(),r(B,null,{default:E(()=>[i(o,{id:"mermaid-53",class:"mermaid",graph:"flowchart%20TD%0A%20%20BAR%5B%22%E7%89%A9%E7%89%A9%E4%BA%A4%E6%8D%A2%EF%BC%9A%E9%9C%80%E6%B1%82%E5%8F%8C%E9%87%8D%E5%B7%A7%E5%90%88%E9%9A%BE%E9%85%8D%22%5D%20--%3E%20COST%5B%22%E5%8C%B9%E9%85%8D%E4%B8%8E%E8%AE%AE%E4%BB%B7%E6%88%90%E6%9C%AC%E9%AB%98%22%5D%0A%20%20MOE%5B%22%E6%94%AF%E4%BB%98%E5%AA%92%E4%BB%8B%E6%8C%89%E9%9D%A2%E5%80%BC%E8%A2%AB%E6%8E%A5%E5%8F%97%22%5D%20--%3E%20CHEAP%5B%22%E4%B9%B0%E5%8D%96%E4%B8%8D%E5%90%8C%E6%AD%A5%E4%B9%9F%E8%83%BD%E6%B8%85%E7%AE%97%22%5D%0A%20%20ACC%5B%22%E5%A4%9A%E6%95%B0%E4%BA%BA%E7%9B%B8%E4%BF%A1%E5%AE%83%E4%BC%9A%E8%A2%AB%E6%8E%A5%E5%8F%97%22%5D%20--%3E%20LIQ%5B%22%E5%AE%83%E8%8E%B7%E5%BE%97%E6%B5%81%E5%8A%A8%E6%80%A7%22%5D%0A%20%20LIQ%20--%3E%20ACC%0A%20%20RUN%5B%22%E6%8C%A4%E5%85%91%EF%BC%9A%E9%9D%A2%E5%80%BC%E5%85%91%E6%8D%A2%E4%B8%AD%E6%96%AD%22%5D%20--%3E%20EXIT%5B%22%E5%90%8C%E4%B8%80%E8%B4%9F%E5%80%BA%E9%80%80%E5%87%BA%20M%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=n('<p><span class="marginnote">常见误区：以为「钱都是央行印的」，所以 M 由央行说了算。公众手里的 M 大头其实是商业银行的存款（内部货币）——你扫码付出去的钱躺在银行账本上；央行直接控制的只有通货加准备金那一层（外部货币）。这决定了「谁在征收通胀税」和后课乘数故事对不对。</span></p><p>层次漂移：货币市场基金、支付账户使准货币更像 \\(M1\\)，货币需求函数移位。Friedman 强调定义要随制度，否则下一课的速度会表现为「突变」而其实是口径。名义锚从这里开始：没有被接受的媒介，SNA 的名义 \\(Y\\) 仍可记账，但「价格水平」缺一个货币面。</p><p><span class="marginnote">贷款创造存款，再找准备金。乘数故事把顺序写反，留给<a href="/econ/reserve-endogenous-money">准备金课</a>。本课只承认：公众持有的媒介大量是银行存款，不是铸币。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把国债、股票、房产算进交易用 \\(M\\)，即使它们能保值。也不要把加密代币在未成为普遍清算工具时写成新的 \\(M0\\)。量化栏的报价与成交是微观价格发现，本栏的货币是宏观支付存量。本课不讨论最优通胀；Friedman 的最优货币量要有机会成本，留给数量与铸币税。开放经济的美元化：外国媒介取代本国 \\(M\\)，铸币税外流，三角课再提。</p><p>后课默认：写下 \\(M\\) 时，指的是支付口径的存量，并声明层次。下一课把 \\(M\\) 接到 \\(P\\) 与 \\(y\\)。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>增长账是实物；货币课从支付手段开始。</li><li>层次按流动性划分；\\(M\\) 不是一切财富。</li><li>内部货币是银行负债，外部货币才直接通向铸币税。</li><li>接受是均衡；挤兑使同一负债退出 \\(M\\)。</li><li>速度、中性、通胀税都建立在本课的 \\(M\\) 上。</li><li>出处：Hicks, Economica 1935；Friedman 的货币需求与购买力栖所传统。</li></ul>',8))])}const C=s(p,[["render",d]]);export{u as __pageData,C as default};
